type VisualizerProps = {
  frame: number;
};

const Visualizer: React.FC<VisualizerProps> = ({ frame }) => {
  const bars = [1, 2, 3, 4, 5, 6, 7];
  return (
    <div style={{ display: "flex", gap: "3px", alignItems: "center", height: "24px" }}>
      {bars.map((i) => {
        const height = interpolate(
          Math.sin(frame * 0.15 + i * 1.2) + Math.cos(frame * 0.08 + i * 0.5),
          [-2, 2],
          [4, 24]
        );
        return (
          <div key={i} style={{
            width: "3px",
            height: `${Math.max(4, height)}px`,
            backgroundColor: "rgba(255,255,255,0.9)",
            borderRadius: "2px"
          }} />
        );
      })}
    </div>
  );
};

type ProgressBarProps = {
  frame: number;
  durationInFrames: number;
};

const ProgressBar: React.FC<ProgressBarProps> = ({ frame, durationInFrames }) => {
  const progress = interpolate(frame, [0, durationInFrames], [0, 100], { extrapolateRight: "clamp" });
  return (
    <div style={{
      flex: 1,
      height: "5px",
      backgroundColor: "rgba(255,255,255,0.2)",
      borderRadius: "3px",
      position: "relative",
      overflow: "hidden"
    }}>
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        height: "100%",
        width: `${progress}%`,
        backgroundColor: "white",
        borderRadius: "3px"
      }} />
    </div>
  );
};

