type AnimatedTranscriptProps = {
  text: string;
  frame: number;
  fps: number;
  color: string;
};

const AnimatedTranscript: React.FC<AnimatedTranscriptProps> = ({ text, frame, fps, color }) => {
  const words = text.split(" ");
  
  // Continuous scroll progress based on word reveal speed (4 frames per word, approx 5 words per line, 100px per line height)
  const currentWordProgress = (frame - 35) / 4;
  const currentLineProgress = currentWordProgress / 5;
  
  // Start scrolling after 2 lines to keep the active text roughly centered in the view
  const scrollY = Math.max(0, (currentLineProgress - 2) * 100);

  return (
    <div style={{
      height: "460px",
      position: "relative",
      overflow: "hidden", // Clips the text strictly within this box
    }}>
      <div style={{
        display: "flex",
        flexWrap: "wrap",
        columnGap: "24px",
        rowGap: "10px",
        alignItems: "flex-start",
        transform: `translateY(-${scrollY}px)`,
        paddingTop: "10px",
        paddingBottom: "80px", // Breathing room at the bottom
      }}>
        {words.map((word, i) => {
          const delay = 35 + i * 4;
          const introOpacity = spring({ frame: frame - delay, fps, config: { damping: 14, mass: 0.6 } });
          const y = interpolate(introOpacity, [0, 1], [35, 0]);
          const blurAmount = interpolate(introOpacity, [0, 1], [15, 0]);

          // Fade out older words mathematically to create a scrolling "chunk" effect
          const distanceBehind = currentWordProgress - i;
          const fadeOutOpacity = interpolate(
            distanceBehind,
            [12, 20], // Starts fading 12 words behind, fully invisible by 20 words behind
            [1, 0.05],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const finalOpacity = introOpacity * fadeOutOpacity;

          return (
            <span key={i} style={{
              opacity: finalOpacity,
              transform: `translateY(${y}px)`,
              filter: `blur(${blurAmount}px)`,
              fontSize: "88px",
              lineHeight: "1.05",
              fontWeight: "700",
              color: color,
              display: "inline-block",
              letterSpacing: "-2.5px"
            }}>
              {word}
            </span>
          );
        })}
      </div>
    </div>
  );
};

